(()=>{
 const keys=[['ride-pivot','pivotPct'],['ride-pivot-z','pivotZ'],['ride-wire','wire'],['ride-mean','mean'],['ride-coils','activeCoils'],['ride-free','freeLength'],['ride-preload','preload'],['ride-travel','travel'],['ride-extension','extension'],['ride-drive-k','driveK'],['ride-front-k','frontTireK'],['ride-rear-k','rearK'],['ride-ax','ax'],['ride-mu','mu']];
 const names={air:'접촉 이탈',tire:'타이어 지지',spring:'스프링 작동','droop-stop':'리바운드 스톱','bump-stop':'압축 스톱'};
 const fmt=(v,d=1)=>Number.isFinite(v)?v.toFixed(d):'—';let animation=null;
 function diagram(a,b){const top=p=>[170+p[0]*.34,192-p[1]*.34],shape=poly=>poly.map((p,i)=>(i?'L':'M')+top(p).join(' ')).join(' ')+'Z';let out='<text x="20" y="25" fill="#668052" font-size="11">XY 접촉 지지 (좌) / XZ 측면 (우) · 측면 변위 3배 확대</text>';
  const base=[[-params.L/2,-params.W/2],[params.L/2,-params.W/2],[params.L/2,params.W/2],[-params.L/2,params.W/2]];out+=`<path d="${shape(base)}" fill="#e5ebdc" stroke="#b9c6ae"/><path d="${shape(a.hull)}" fill="#cbddba" fill-opacity=".6" stroke="#8b9f70" stroke-dasharray="4 3"/>`;
  for(const r of a.rows){const p=top(r.point);out+=`<circle cx="${p[0]}" cy="${p[1]}" r="${r.index<2?11:8}" fill="${r.contact?r.index<2?'#75a28a':'#c2a36d':'#c68564'}" stroke="#f1f4e9" stroke-width="2"/><text x="${p[0]}" y="${p[1]-16}" text-anchor="middle" fill="#5e7e4d" font-size="10">${r.name.split(' ')[0]}</text><text x="${p[0]}" y="${p[1]+25}" text-anchor="middle" fill="${r.contact?'#5d7b4c':'#a56c49'}" font-size="10">${fmt(r.force,0)} N</text>`;}
  const cg=top([a.cg[0],a.cg[1]]),eq=top([a.xEffective,a.cg[1]]);out+=`<circle cx="${cg[0]}" cy="${cg[1]}" r="4" fill="#bd8c5b"/><path d="M${eq[0]-6} ${eq[1]}H${eq[0]+6}M${eq[0]} ${eq[1]-6}V${eq[1]+6}" stroke="#466d83" stroke-width="2"/><text x="22" y="340" fill="#738866" font-size="10">원: CG / 십자: 등가 가속도 하중점</text><text x="22" y="359" fill="#738866" font-size="10">반력이 0인 바퀴는 지지 다각형에서 제외합니다.</text>`;
  const sx=x=>390+(x+params.L/2)*(330/params.L),sy=z=>330-z*.5,delta=x=>a.q[0]-b.q[0]+(a.q[1]-b.q[1])*x/300;
  out+='<path d="M357 45V385" stroke="#cfdbc4"/><path d="M370 330H742" stroke="#bccab0" stroke-dasharray="4 3"/>';
  out+=`<path d="M${sx(-params.L/2)} ${sy(185+3*delta(-params.L/2))}L${sx(params.L/2)} ${sy(185+3*delta(params.L/2))}" stroke="#8ca580" stroke-width="12"/><text x="404" y="105" fill="#688357" font-size="11">프레임 자세 변화</text><text x="404" y="125" fill="#7d926e" font-size="10">앞들림 ${fmt(a.pitch-b.pitch,2)}° / 좌측들림 ${fmt(a.roll-b.roll,2)}°</text>`;
  for(const i of[0,2,4]){const r=a.rows[i],x=sx(r.point[0]),reference=b.rows[i],g=sy(3*r.ground),bodyDelta=r.bodyDelta||0,center=sy(r.point[2]+3*(bodyDelta+(rideDesign.bogie?r.relativeDelta||0:r.deltaSpring||0))),radius=r.point[2]*.5;out+=`<path d="M${x-32} ${g}H${x+32}" stroke="#9daa82" stroke-width="5"/><circle cx="${x}" cy="${center}" r="${radius}" fill="${r.contact?'#8ca182':'#bf8f70'}" stroke="#607955"/><circle cx="${x}" cy="${center}" r="${radius*.45}" fill="#e1e8d6"/>${!rideDesign.bogie||i===4?`<path d="M${x} ${center-radius}V${sy(185+3*delta(r.point[0]))}" stroke="#a8b795" stroke-width="4"/>`:''}<text x="${x}" y="${g+20}" text-anchor="middle" fill="#71885f" font-size="10">${r.name.split(' ')[0]} ${r.ground>0?'+':''}${r.ground} mm</text>`;}
  if(rideDesign.bogie){const L=bogieLayout(),rD=a.rows[0],rC=a.rows[2],yd=sy(100+3*((rD.bodyDelta||0)+(rD.relativeDelta||0))),yc=sy(96+3*((rC.bodyDelta||0)+(rC.relativeDelta||0))),yp=sy(L.pz+3*delta(L.px));out+=`<path d="M${sx(0)} ${yd}L${sx(L.px)} ${yp}L${sx(L.front)} ${yc}" fill="none" stroke="#bd935c" stroke-width="7"/><circle cx="${sx(L.px)}" cy="${yp}" r="7" fill="#f3f1dc" stroke="#8d775a"/><text x="${sx(L.px)}" y="${yp-15}" text-anchor="middle" fill="#98764e" font-size="10">보기 Y 피벗</text>`;}
  return out+'<text x="390" y="393" fill="#7c8e6d" font-size="10">측면은 좌측 휠을 표시 · 충격·진동 시간응답은 계산하지 않습니다.</text>';
 }
 function sync(){for(const [id,key]of keys){$(id).value=rideDesign[key];const o=$(id+'-out');if(o)o.textContent=rideDesign[key];}rideDesign.terrain.forEach((v,i)=>{$('ride-ground-'+i).value=v;$('ride-ground-'+i+'-out').textContent=(v>0?'+':'')+v+' mm';});rideDesign.swivel.forEach((v,i)=>{$('ride-swivel-'+i).value=v;$('ride-swivel-'+i+'-out').textContent=v+'°';});$('ride-enabled').checked=rideDesign.enabled;$('ride-bogie').checked=rideDesign.bogie;}
 window.renderRideReview=()=>{sync();$('suspension-review').hidden=rideDesign.enabled;$('bogie').disabled=rideDesign.enabled;if(rideDesign.enabled){suspension.bogie=false;suspension.preload=false;$('bogie').checked=false;$('preload').checked=false;$('preload').disabled=true;}
  const {current:a,baseline:b}=rideAnalysis(),s=rideSpring();$('bogie-detail').hidden=!rideDesign.bogie;$('ride-spring-result').innerHTML=`<b>k = ${fmt(s.k,2)} N/mm</b> · 외경 ${fmt(rideDesign.mean+rideDesign.wire)} mm<br>총 권수 ${fmt(s.total)} / 추정 밀착장 ${fmt(s.solid)} mm<br>초기 압축 ${fmt(s.preCompression)} mm / 밀착 전 추가 스트로크 ${fmt(s.maxStrokeBeforeSolid)} mm<br>설정 전 스트로크의 밀착 여유 ${fmt(s.maxStrokeBeforeSolid-rideDesign.travel)} mm`;
  if(!a.ok||!b.ok){$('ride-diagram').innerHTML='<text x="380" y="195" text-anchor="middle" fill="#a2744c">가정한 수직 지지 조건에서 정적 평형을 찾지 못했습니다.</text>';$('ride-metrics').innerHTML='';$('ride-rows').innerHTML='';$('bogie-rows').innerHTML='';$('ride-assessment').textContent='접촉점·하중점·요철을 조정해야 합니다. 현재 이후의 회전·전도 운동은 계산하지 않습니다.';$('ride-assessment').classList.add('warn');$('ride-camera').innerHTML='기준 평형이 없어 포락 계산을 보류합니다.';return;}
  $('ride-diagram').innerHTML=diagram(a,b);$('bogie-rows').innerHTML=(a.bogies||[]).map((v,i)=>`<tr><td>${v.side>0?'좌측':'우측'}</td><td>${v.pivot.map(x=>fmt(x)).join(', ')}</td><td>${fmt(v.angle-b.bogies[i].angle,2)}°</td><td>${fmt(v.stroke)} / ${rideDesign.travel} mm</td><td>${fmt(v.springForce)} N</td><td>${names[v.state]} / ${fmt(v.stopForce)} N</td><td>${fmt(v.momentResidual,6)} N·m</td></tr>`).join('');const count=a.rows.filter(r=>r.contact).length,normal=Math.min(a.rows[0].force,a.rows[1].force);$('ride-metrics').innerHTML=`<div><span>수직 반력이 있는 바퀴</span><strong>${count} / 5</strong></div><div><span>구동륜 최소 반력</span><strong>${fmt(normal)} N</strong></div><div><span>구동 접선력 요구 / 한계 가정</span><strong>${fmt(a.tractionRequired,0)} / ${fmt(a.traction,0)} N</strong></div>`;
  $('ride-rows').innerHTML=a.rows.map(r=>`<tr class="${!r.contact||r.state==='bump-stop'?'warning':''}"><td>${r.name}</td><td>${r.point.slice(0,2).map(v=>fmt(v,0)).join(', ')}</td><td>${r.ground}</td><td>${fmt(r.force)}</td><td>${r.front?fmt(r.spring)+' / '+rideDesign.travel:'—'}</td><td>${fmt(r.tireDeflection,2)}</td><td>${names[r.state]}${r.gap>.01?'<small>지면 간격 '+fmt(r.gap)+' mm</small>':''}${r.stopForce>0?'<small>스톱 반력 '+fmt(r.stopForce)+' N</small>':''}</td></tr>`).join('');
  const issues=[];for(const r of a.rows){if(!r.contact)issues.push(r.name+' 접촉 이탈');if(r.state==='bump-stop')issues.push(r.name+' 압축 스톱 도달');}if(a.tractionRatio>1)issues.push('가정 마찰계수의 구동 접선력 한계 초과');if(a.solidMargin<4)issues.push('현재 코일 밀착 여유 4 mm 미만');if(s.maxStrokeBeforeSolid-rideDesign.travel<4)issues.push('설정 전 스트로크에서 코일 밀착 여유 4 mm 미만');if(!a.modelRange)issues.push('차체 5° 또는 보기 10° 초과: 소각도 모델 범위 주의');
  $('ride-assessment').textContent=(!rideDesign.enabled?'3D 적용 꺼짐. ':'')+(issues.length?issues.join(' · '):'현재 입력에서 5휠 접촉과 가정한 스프링 작동 범위를 유지합니다.')+(rideDesign.bogie?' 좌우 보기·코일·타이어 결합 준정적 결과입니다.':' 독립 수직현가 비교 결과입니다.')+' 실물 성능이나 전도 궤적을 뜻하지 않습니다.';$('ride-assessment').classList.toggle('warn',!!issues.length);
  $('ride-balance').textContent=`총질량 ${fmt(a.total)} kg / ΣN ${fmt(a.rows.reduce((v,r)=>v+r.force,0),2)} N / 힘 잔차 ${fmt(a.residual[0],6)} N / 전후·좌우 모멘트 잔차 ${fmt(a.residual[1]*.3,6)}, ${fmt(a.residual[2]*.3,6)} N·m. 현재 접촉 다각형의 등가 하중점 여유 ${fmt(a.margin)} mm.`;
  const cam=rideCameraClearances();$('ride-camera').innerHTML=cam.map(r=>`<div class="${r.clear?'ok':'warn'}"><span>${r.side>0?'L':'R'} · ${r.part} ↔ ${r.against}</span><strong>${fmt(r.gap)} mm</strong><small>${r.clear?'예약 포락 분리':'포락 중첩 / 정밀 형상 검토 필요'}</small></div>`).join('');
  const currentSpringLoads=rideDesign.bogie?a.bogies.map(v=>v.springForce):a.rows.filter(r=>r.front).map(r=>Math.max(rideDesign.preload,Math.min(r.force,rideDesign.preload+s.k*rideDesign.travel)));$('ride-spring-stress').textContent=`현재 코일 하중 L/R ${currentSpringLoads.map(v=>fmt(v)).join(' / ')} N · Wahl 보정 전단응력 ${currentSpringLoads.map(v=>fmt(s.stress(v),0)).join(' / ')} MPa. 현재 최소 밀착 여유 ${fmt(a.solidMargin)} mm. 재질 허용응력·피로 수명·좌굴·실제 카탈로그 허용 변위는 아직 판정하지 않습니다.`;
  if(rideDesign.enabled){$('model-status').innerHTML=`<b>5휠 · ${rideDesign.bogie?'좌우 보기 링크 연결':'독립 수직현가 비교'} / 접촉 ${count}개</b><br>${rideDesign.bogie?'모터·구동휠·캐스터 동반 회전 / ':'캐스터 독립 이동 / '}C-L 바닥 ${rideDesign.terrain[2]} mm / 코일 압축 ${fmt(a.rows[2].spring)} mm`;if(mechanism.scope==='base')$('live-load-summary').textContent=`준정적 접촉 ${count}/5 · 구동륜 최소 ${fmt(normal)} N · C-L/C-R 압축 ${fmt(a.rows[2].spring)}/${fmt(a.rows[3].spring)} mm · 차체 고정 좌표 표시`;}
 };
 function refresh(){rideCache=null;window.renderRideReview();inspector();draw();}
 function stop(){if(animation){clearInterval(animation);animation=null;}$('ride-animate').textContent='캐스터 360° 선회 보기';$('ride-animate').setAttribute('aria-pressed','false');}
 for(const [id,key]of keys)$(id).addEventListener('input',()=>{const el=$(id),v=+el.value;if(el.value===''||!Number.isFinite(v)||v<+el.min||v>+el.max)return;stop();rideDesign[key]=v;refresh();});
 for(let i=0;i<5;i++)$('ride-ground-'+i).oninput=()=>{stop();rideDesign.terrain[i]=+$('ride-ground-'+i).value;refresh();};for(let i=0;i<3;i++)$('ride-swivel-'+i).oninput=()=>{stop();rideDesign.swivel[i]=+$('ride-swivel-'+i).value;refresh();};
 $('ride-bogie').onchange=()=>{stop();rideDesign.bogie=$('ride-bogie').checked;rideDesign.enabled=true;refresh();};
 $('ride-enabled').onchange=()=>{stop();rideDesign.enabled=$('ride-enabled').checked;if(rideDesign.enabled){suspension.bogie=false;suspension.preload=false;}else{$('bogie').disabled=false;}window.renderSuspensionReview();refresh();};
 const preset=(type)=>{stop();rideDesign.terrain=type==='flat'?[0,0,0,0,0]:type==='diagonal'?[20,0,0,20,0]:type==='hole'?[0,0,-40,0,0]:[0,0,15,0,0];rideDesign.ax=type==='brake'?-1.2:0;refresh();};document.querySelectorAll('[data-ride-case]').forEach(b=>b.onclick=()=>preset(b.dataset.rideCase));
 $('ride-old').onclick=()=>{stop();rideDesign={...freshRide(),freeLength:75,travel:25};cameraDesign={...cameraDefaults,z:135};window.renderCameraReview();refresh();};$('ride-improved').onclick=()=>{stop();rideDesign=freshRide();cameraDesign={...cameraDefaults};window.renderCameraReview();refresh();};
 $('ride-animate').onclick=()=>{if(animation){stop();return;}const start=[...rideDesign.swivel];let step=0;$('ride-animate').textContent='선회 검토 중지';$('ride-animate').setAttribute('aria-pressed','true');animation=setInterval(()=>{step++;rideDesign.swivel=start.map(v=>(v+step*15)%360);rideCache=null;if(step>=24){rideDesign.swivel=start;stop();refresh();return;}rideDesign.swivel.forEach((v,i)=>{$('ride-swivel-'+i).value=v;$('ride-swivel-'+i+'-out').textContent=v+'°';});draw();},120);};
 $('ride-focus').onclick=()=>{mechanism.scope='base';partGroup='base';window.renderMechanismReview();document.querySelectorAll('[data-group]').forEach(b=>b.classList.toggle('active',b.dataset.group==='base'));select(rideDesign.bogie?'bogie':'caster');zoom=1;setView('iso');if($('expand-view').getAttribute('aria-pressed')!=='true')$('expand-view').click();$('model').scrollIntoView({block:'center'});};
 window.renderRideReview();mechanism.scope='base';partGroup='base';window.renderMechanismReview();select(rideDesign.bogie?'bogie':'caster');yaw=.95;elevation=.58;zoom=1;draw();
})();
